import {cloudScanStatus,enableCloudScan,scanCloudTicket} from './cloud-scan.js?v=0.20.5';
export function openTicketScanner(apply){const d=document.createElement('dialog');d.className='scanner-dialog';document.body.append(d);let stream=null,closed=false,inflight=null;const stop=()=>{stream?.getTracks().forEach(t=>t.stop());stream=null;};const close=()=>{closed=true;inflight?.abort();stop();d.close();d.remove();};const fail=e=>{if(closed)return;const output=d.querySelector('[role=alert]');if(output)output.textContent=e.message;};d.addEventListener('cancel',e=>{e.preventDefault();close();});const choosePhotoHTML=`<label class="scanner-file-choice">Choose from photo library<input type="file" id="scanner-file" accept="image/*" hidden></label><label class="scanner-file-choice">Use iPhone camera / flash<input type="file" id="scanner-native-camera" accept="image/*" capture="environment" hidden></label>`;
 const bindFile=()=>{for(const input of d.querySelectorAll('#scanner-file,#scanner-native-camera'))input.onchange=()=>{const file=input.files[0];if(file)recognize(file);};};
 const recognize=async file=>{stop();if(closed)return;inflight=new AbortController();d.innerHTML=`<h2>Reading your ticket…</h2><div class="scan-reading-mark" aria-hidden="true">⌕</div><p role="status">Filling in the name, phone and address. This usually takes a few seconds.</p><p class="muted">Processed temporarily by Cloudflare. The photo isn’t saved in our app or scanner service.</p><button id="scanner-close">Cancel scan</button>`;d.querySelector('#scanner-close').onclick=close;try{const result=await scanCloudTicket(file,{signal:inflight.signal});if(closed)return;apply(result);close();}catch(e){if(closed)return;d.innerHTML=`<h2>Let’s try that again.</h2><p class="error" role="alert"></p><div class="actions"><button class="primary" id="scanner-retry">Open camera</button>${choosePhotoHTML}<button id="scanner-close">Cancel</button></div>`;fail(e);d.querySelector('#scanner-close').onclick=close;d.querySelector('#scanner-retry').onclick=()=>cloudScanStatus().enabled?camera():setup();bindFile();}};
 const camera=async()=>{if(closed)return;d.innerHTML=`<h2>Scan the ticket</h2><p>Keep the name, phone and full address—including the unit—inside the frame.</p><div class="camera-frame"><video autoplay muted playsinline></video><div class="camera-guide"></div></div><div class="actions"><button class="primary" id="capture-ticket" disabled>Take photo</button><button id="torch" hidden>Turn flashlight on</button><button id="scanner-close">Cancel</button></div><div class="scanner-other">${choosePhotoHTML}</div><p class="muted">Cloudflare processes this capture temporarily. No ticket images or extracted text are stored in the scanner service.</p><p class="error" role="alert"></p>`;d.querySelector('#scanner-close').onclick=close;bindFile();try{if(!navigator.mediaDevices?.getUserMedia)throw Error('Rear camera unavailable here. Use the native camera option below.');const opened=await navigator.mediaDevices.getUserMedia({audio:false,video:{facingMode:{exact:'environment'},width:{ideal:1920},height:{ideal:1440}}});if(closed){opened.getTracks().forEach(t=>t.stop());return;}stream=opened;const video=d.querySelector('video');if(!video){stop();return;}video.srcObject=stream;await video.play();if(closed)return;d.querySelector('#capture-ticket').disabled=false;const track=stream.getVideoTracks()[0];if(track.getCapabilities?.().torch){const button=d.querySelector('#torch');button.hidden=false;button.setAttribute('aria-pressed','false');let on=false;button.onclick=async()=>{try{const next=!on;await track.applyConstraints({advanced:[{torch:next}]});on=next;button.setAttribute('aria-pressed',String(on));button.textContent=on?'Turn flashlight off':'Turn flashlight on';}catch(e){fail(Error('Flashlight control isn’t available. Use room lighting or the native camera option.'));}};}else{const note=document.createElement('p');note.className='muted';note.textContent='This browser does not offer flashlight control. Use iPhone camera / flash below for the phone’s own camera controls.';d.querySelector('.scanner-other').append(note);}d.querySelector('#capture-ticket').onclick=()=>{if(video.videoWidth===0)return;d.querySelector('#capture-ticket').disabled=true;const frame=document.createElement('canvas');frame.width=video.videoWidth;frame.height=video.videoHeight;frame.getContext('2d').drawImage(video,0,0);frame.toBlob(blob=>{frame.width=0;frame.height=0;if(blob)recognize(blob);else fail(Error('Could not capture the photo.'));},'image/jpeg',.95);};}catch(e){stop();if(!closed)fail(Error('Rear camera could not open here. Use the native camera option or enter manually.'));}};
 const setup=()=>{const status=cloudScanStatus();d.innerHTML=`<form><h2>Enable in-app ticket scanning</h2><p>Capture a ticket here and have its delivery fields filled automatically.</p><p class="muted">The photo—including names, numbers and addresses—is sent to Cloudflare for temporary recognition. Our scanner does not store photos or extracted text, or log their content. Cloudflare’s zero-retention policy has security/legal exceptions. Your saved delivery records and CSV exports stay on this device.</p>${status.canReuseDevice?'<p>This phone’s existing driver setup can connect the scanner.</p>':'<label>Driver setup code<input name="code" type="password" autocomplete="off" required></label>'}<p class="muted">Uses the free scanning allowance. No paid plan or automatic paid fallback. This setup is only needed once per installation.</p><p class="error" role="alert"></p><div class="actions"><button type="button" id="scanner-close">Cancel</button><button class="primary" type="submit">Enable scanner & open camera</button></div></form>`;d.querySelector('#scanner-close').onclick=close;d.querySelector('form').onsubmit=async e=>{e.preventDefault();const button=d.querySelector('[type=submit]');button.disabled=true;try{await enableCloudScan(new FormData(e.target).get('code')||'');if(!closed)camera();}catch(e){fail(e);if(button.isConnected)button.disabled=false;}};};d.showModal();cloudScanStatus().enabled?camera():setup();}
